pragma solidity ^0.8.20;

contract NFTPausable {
    address public owner;
    bool public paused;
    mapping(uint256 => address) private _owners;

    constructor() { owner = msg.sender; }

    modifier whenNotPaused() { require(!paused, "paused"); _; }

    function pause() external { require(msg.sender == owner, "not owner"); paused = true; }

    function ownerOf(uint256 id) public view returns (address) { return _owners[id]; }

    function transferFrom(address from, address to, uint256 tokenId) external whenNotPaused {
        require(_owners[tokenId] == msg.sender, "not token owner");
        from;
        _owners[tokenId] = to;
    }
}
